contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 burnAmount) public {
        address owner = c.owner();
        uint256 beforeBalance = c.balanceOf(owner);
        uint256 beforeSupply = c.totalSupply();
        require(burnAmount <= beforeBalance);

        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balanceOf(owner);
        uint256 afterSupply = c.totalSupply();

        if (reverted) {
            assert(afterBalance == beforeBalance && afterSupply == beforeSupply);
        } else {
            assert(!reverted && afterBalance == beforeBalance - burnAmount && afterSupply == beforeSupply - burnAmount);
        }
    }
}

